// a plain {x,y,width,height} object, .right()=x+width, no getters/
// setters, so directly narrowing .width is safe) and by confirming
// Neume.finishLayout is the base class method shared by every neume
// subclass (Podatus, Clivis, etc. only override positionMarkings(), not
// finishLayout itself), so this applies uniformly. Please test in the
// browser against the reported "stellárum" case and report back.
(function patchNeumeFinalNoteBoundsForSpacing() {
  const cls = exsurge.Neume;
  if (!cls) return;
  const orig = cls.prototype.finishLayout;
  cls.prototype.finishLayout = function(ctxt) {
    orig.call(this, ctxt);
    if (!this.notes || !this.notes.length) return;
    let coreRight = -Infinity;
    for (const note of this.notes) {
      if (note.bounds) coreRight = Math.max(coreRight, note.bounds.right());
    }
    const lastNote = this.notes[this.notes.length - 1];
    const lastNoteMarkings = []
      .concat(lastNote.morae || [])
      .concat(lastNote.epismata || [])
      .concat(lastNote.ictus ? [lastNote.ictus] : [])
      .concat(lastNote.acuteAccent ? [lastNote.acuteAccent] : []);
    for (const m of lastNoteMarkings) {
      if (m && m.bounds) coreRight = Math.max(coreRight, m.bounds.right());
    }
    if (coreRight > -Infinity && coreRight < this.bounds.right()) {
      this.bounds.width = coreRight - this.bounds.x;
    }
  };
})();

